package cn.zhuatech.hragent.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class EmployeeCaseDecisionReleaseService{public Assessment assess(Request r){List<String>b=new ArrayList<>(),a=new ArrayList<>();if(!r.policyBasisVerified())b.add("员工案件处理缺少有效制度依据");if(!r.needToKnowAccessApplied())b.add("案件访问未按知悉必要限制");if(!r.protectedAttributesExcluded())b.add("AI 建议不当使用受保护属性");if(!r.evidenceReviewed())b.add("案件证据未完成复核");if(!r.humanDecisionMakerAssigned())b.add("最终人工决策人未指定");if(r.highRiskDecision()&&!r.hrAndLegalReviewComplete())b.add("高风险人事决定缺少 HR 与法务复核");if(!r.employeeNoticeReady())b.add("员工告知材料未准备");if(!r.finalApprovalComplete())b.add("案件决定发布审批未完成");if(!b.isEmpty()){a.add("阻断案件决定发布并完成合规与证据复核");return new Assessment(Decision.BLOCKED,b,a);}if(!r.appealChannelReady()||!r.retentionPolicyApplied()){if(!r.appealChannelReady())a.add("建立员工询问与申诉渠道");if(!r.retentionPolicyApplied())a.add("应用案件资料保留与删除策略");return new Assessment(Decision.HR_REVIEW,b,a);}a.add("发布决定并归档制度、证据、审批和员工告知记录");return new Assessment(Decision.RELEASE,b,a);}public record Request(@NotBlank String caseId,boolean policyBasisVerified,boolean needToKnowAccessApplied,boolean protectedAttributesExcluded,boolean evidenceReviewed,boolean humanDecisionMakerAssigned,boolean highRiskDecision,boolean hrAndLegalReviewComplete,boolean employeeNoticeReady,boolean appealChannelReady,boolean retentionPolicyApplied,boolean finalApprovalComplete){}public record Assessment(Decision decision,List<String>blockers,List<String>actions){}public enum Decision{RELEASE,HR_REVIEW,BLOCKED}}
